{"path": "/tmp/sv-00bbf7e7ca304566a6cfd43537eb0382/Services/AppointmentService.cs", "file_text": "using sv_00bbf7e7ca304566a6cfd43537eb0382.Models;

namespace sv_00bbf7e7ca304566a6cfd43537eb0382.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Patel"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Williams"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }

        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates patient info against server-side business rules.
    /// Stub: rejects "taken@example.com" (balance), "None" insurance with "Dr. Smith" (self-pay),
    /// and "10:00 AM" time slot (race condition).
    /// </summary>
    public Task<PatientValidationResult> ValidatePatientAsync(AppointmentFormModel model)
    {
        var result = new PatientValidationResult();

        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(model.Email)] = "Account has outstanding balance";
        }

        if (model.InsuranceProvider == "None"
            && string.Equals(model.Doctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(model.Doctor)] = "Selected doctor does not accept self-pay patients";
        }

        if (model.TimeSlot == "10:00 AM")
        {
            result.Errors[nameof(model.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }
}
"}

